<script setup lang="ts">
const route=useRoute(),{api,restore,money,message}=useMarketplace()
const order=ref<any>(null),busy=ref(true),error=ref('')
const labels:Record<string,string>={PENDING:'در انتظار پردازش',PROCESSING:'در حال آماده‌سازی',SHIPPED:'ارسال شده',DELIVERED:'تحویل شده',CANCELLED:'لغو شده'}
async function load(){busy.value=true;error.value='';try{await restore();order.value=await api(`/api/orders/${encodeURIComponent(String(route.params.id))}`)}catch(e){error.value=message(e)}finally{busy.value=false}}
onMounted(load)
useHead({title:'پیگیری سفارش | پارتلی'})
</script>
<template><section class="shell py-12"><h1 class="market-title">پیگیری سفارش</h1><p v-if="busy" class="market-empty">در حال دریافت سفارش…</p><div v-else-if="error" class="market-error">{{error}} <button class="underline" @click="load">تلاش دوباره</button><NuxtLink to="/login" class="mr-4 underline">ورود</NuxtLink></div><article v-else-if="order" class="market-panel mt-8"><div class="mb-6 flex flex-wrap justify-between gap-4"><div><h2 class="text-lg font-bold">سفارش {{order.id.slice(-8).toUpperCase()}}</h2><p class="mt-2 text-xs text-slate-500">{{new Date(order.createdAt).toLocaleString('fa-IR')}}</p></div><span class="market-badge h-fit">{{labels[order.status]}}</span></div><div class="market-success">سفارش ثبت شده است. وضعیت آماده‌سازی و ارسال در همین صفحه به‌روزرسانی می‌شود.</div><div class="mb-6 rounded-xl bg-slate-50 p-5 text-sm leading-8"><p>{{order.name}} · {{order.phone}}</p><p>{{order.address}}</p><p>کد پستی: {{order.postalCode}}</p><p v-if="order.note">توضیحات: {{order.note}}</p></div><div class="overflow-x-auto"><table class="market-table"><thead><tr><th>کالا</th><th>تعداد</th><th>وضعیت</th><th>جمع</th></tr></thead><tbody><tr v-for="item in order.items" :key="item.id"><td>{{item.name}}<p class="text-xs text-slate-400">{{item.sku}}</p></td><td>{{item.quantity}}</td><td>{{labels[item.status]}}</td><td>{{money(Number(item.price)*item.quantity)}}</td></tr></tbody></table></div><div class="mt-6 flex flex-wrap justify-between gap-3"><span class="text-sm text-slate-500">روش پرداخت: پرداخت در محل</span><strong>{{money(order.total)}}</strong></div><NuxtLink to="/account" class="market-secondary mt-8">همه سفارش‌های من</NuxtLink></article></section></template>
